/// 带 CDS/provider 两层的壳：
///
/// - CDS 侧（[_cds]）会被静默换成新对象（只有 roomSeq 变化）
/// - provider 侧（[_messages]）判定渲染内容没变就跳过更新，屏幕一直拿着旧对象
class _CdsBackedHarness extends StatefulWidget {
  final List<ChatMessage> messages;

  const _CdsBackedHarness({super.key, required this.messages});

  @override
  State<_CdsBackedHarness> createState() => _CdsBackedHarnessState();
}

class _CdsBackedHarnessState extends State<_CdsBackedHarness> {
  final ScrollController controller = ScrollController();
  late List<ChatMessage> _cds = [...widget.messages];
  late List<ChatMessage> _messages = List.of(_cds);
  final Set<String> _entranceKeys = {};

  void sendFromCds(List<ChatMessage> messages) {
    _cds = [..._cds, ...messages];
    _publish();
  }

  /// 复刻 _adoptServerFields：同一条逻辑消息换成新对象，只有 roomSeq 变了。
  void swapTailInvisibly(int roomSeq) {
    final swapped = [..._cds];
    swapped[swapped.length - 1] = swapped.last.copyWith(roomSeq: roomSeq);
    _cds = swapped;
    _publish();
  }

  void _publish() {
    final needsUpdate =
        _messages.length != _cds.length ||
        ![
          for (var i = 0; i < _cds.length; i++)
            ChatMessage.sameRenderedContent(_cds[i], _messages[i]),
        ].every((same) => same);
    if (!needsUpdate) return;
    setState(() {
      _entranceKeys.addAll(newlyAppendedMessageKeys(_messages, _cds));
      _messages = List.of(_cds);
    });
  }

  @override
  void dispose() {
    controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return SizedBox(
      height: 400,
      child: MessageListView(
        messages: _messages,
        entranceKeys: _entranceKeys,
        scrollController: controller,
        galleryItems: const [],
        imageIndexById: const {},
        essenceMids: const [],
        pinnedMessages: const [],
        essenceEnabled: false,
        currentRoom: null,
        canModerateGroup: false,
        onRefresh: () {},
