class _MessageListHarnessState extends State<_MessageListHarness> {
  final ScrollController controller = ScrollController();
  late List<ChatMessage> _messages = [...widget.messages];
  final Set<String> _entranceKeys = {};

  void appendWithEntrance(List<ChatMessage> messages) => setState(() {
    final next = [..._messages, ...messages];
    _entranceKeys.addAll(newlyAppendedMessageKeys(_messages, next));
    _messages = next;
  });

  void replaceLast(List<ChatMessage> messages) => setState(() {
    _messages = [..._messages]
      ..removeLast()
      ..addAll(messages);
  });

  @override
  void dispose() {
